/**
 * A claim was shared with another person on a sheet ({@code CLAIM_SHARED}). The person is the claim's own
 * person; the number is the claim's number, or null when it has none; with names the person now holding the
 * share, a percent.
 */
public record ClaimShared(String sheetId, String user, String person, BigDecimal amount, LocalDate date,
        String number, String with, BigDecimal share) {
}
-- The other people on the sheet a claim is shared with, in the order they were added: each holds a share
-- of the claim's due, a percent with two decimals (more than 0.00; a claim's shares total at most 100.00).
-- A claim already there is shared with no one.
CREATE TABLE claim_share (
    claim_id BIGINT NOT NULL REFERENCES claim(id),
    seq INT NOT NULL,
    person_id BIGINT NOT NULL,
    share NUMERIC(5, 2) NOT NULL,
    PRIMARY KEY (claim_id, seq)
);
-- Whether the claim is held: an OPEN or PENDING held claim is left out of the live totals as a held person's are.
ALTER TABLE claim ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
    }

